import * as React from "react";
import { cx } from "./cx";

export function Kbd({ className, ...props }: React.HTMLAttributes<HTMLElement>) {
  return <kbd className={cx("rs-kbd", className)} {...props} />;
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Kbd: keys in the mono stack with a pressed bottom edge ── */
.rs-kbd{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px;font-weight:500;color:var(--text-secondary);background:var(--bg);border:1px solid var(--divider);border-bottom-width:2px;border-radius:var(--radius-sm);padding:2px 6px;line-height:1.2}
.rs-kbd-pair{display:inline-flex;align-items:stretch;margin-inline-start:10px;vertical-align:middle}
.rs-kbd-pair .rs-kbd:first-child{border-start-end-radius:0;border-end-end-radius:0}
.rs-kbd-pair .rs-kbd + .rs-kbd{margin-inline-start:-1px;border-start-start-radius:0;border-end-start-radius:0}
